import{_ as a,o as s,c as e,a2 as i}from"./chunks/framework.DnrXFDHb.js";const o="/images/screenshots/codex-client-first-message.png",k=JSON.parse('{"title":"配置 ChatGPT","description":"把你的中转站请求地址和 API Key 填进 ChatGPT（Codex），发一条测试消息确认配置完成。零基础用户跟着做即可。","frontmatter":{"title":"配置 ChatGPT","description":"把你的中转站请求地址和 API Key 填进 ChatGPT（Codex），发一条测试消息确认配置完成。零基础用户跟着做即可。"},"headers":[],"relativePath":"guide/connect.md","filePath":"guide/connect.md","lastUpdated":1787538964000}'),d={name:"guide/connect.md"};function h(l,t,n,c,r,p){return s(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="配置-chatgpt" tabindex="-1">配置 ChatGPT <a class="header-anchor" href="#配置-chatgpt" aria-label="Permalink to &quot;配置 ChatGPT&quot;">​</a></h1><p>这是最关键的一步：把 ChatGPT 连到你的中转站。做完这一步，<strong>ChatGPT 能正常回复你，就说明配置全部完成</strong>，可以开始用了。</p><h2 id="开始前-先检查材料齐不齐" tabindex="-1">开始前，先检查材料齐不齐 <a class="header-anchor" href="#开始前-先检查材料齐不齐" aria-label="Permalink to &quot;开始前，先检查材料齐不齐&quot;">​</a></h2><p>这一步需要两样东西，缺一不可：</p><table tabindex="0"><thead><tr><th>材料</th><th>怎么拿到</th><th>完成标志</th></tr></thead><tbody><tr><td>API Key</td><td><a href="/guide/api-key">创建 API Key</a></td><td>手里有一串以 <code>sk-</code> 开头的 Key</td></tr><tr><td>中转站网址</td><td>打开中转站（你用来登录、充值、创建 Key 的网站），从浏览器地址栏复制</td><td>能完整抄写</td></tr></tbody></table><p>请求地址这样填：</p><ul><li>中转站页面上如果写了 API 地址，就填那个。</li><li>没有的话，在中转站网址末尾加上 <code>/v1</code>。</li></ul><p>举例：中转站网址是 <code>https://example.com</code>，页面上也没另外写 API 地址，请求地址就填 <code>https://example.com/v1</code>。不要填成 <code>.../v1/chat/completions</code>。</p><div class="warning custom-block"><p class="custom-block-title">⚠️ 没材料先别往下走</p><ul><li>还没创建 API Key？先回 <a href="/guide/api-key">创建 API Key</a>，几分钟就好。</li><li>还没充值？回 <a href="/guide/recharge">充值</a>，不然配置好了也调不通。</li><li>还没装 ChatGPT？回 <a href="/guide/codex-install">安装 ChatGPT</a>。</li></ul></div><h2 id="怎么配置-用-cc-switch" tabindex="-1">怎么配置：用 CC Switch <a class="header-anchor" href="#怎么配置-用-cc-switch" aria-label="Permalink to &quot;怎么配置：用 CC Switch&quot;">​</a></h2><p>配置只需要一个工具：<strong>CC Switch</strong>（一个可视化小工具，有界面、能点鼠标，不用碰任何配置文件）。跟着下面的步骤做就行。</p><hr><h2 id="用-cc-switch-配置" tabindex="-1">用 CC Switch 配置 <a class="header-anchor" href="#用-cc-switch-配置" aria-label="Permalink to &quot;用 CC Switch 配置&quot;">​</a></h2><h3 id="安装并打开-cc-switch" tabindex="-1">安装并打开 CC Switch <a class="header-anchor" href="#安装并打开-cc-switch" aria-label="Permalink to &quot;安装并打开 CC Switch&quot;">​</a></h3><p>打开 <a href="/guide/config-switch">CC Switch 使用教程</a>（里面有下载地址和安装步骤），把 CC Switch 装好并打开。</p><p>装好后你会看到 CC Switch 的主窗口，左边有 Codex、Claude 等工具的入口。</p><h3 id="进入-codex-配置-添加供应商" tabindex="-1">进入 Codex 配置，添加供应商 <a class="header-anchor" href="#进入-codex-配置-添加供应商" aria-label="Permalink to &quot;进入 Codex 配置，添加供应商&quot;">​</a></h3><ol><li>在 CC Switch 里点击 <strong>Codex</strong> 入口。</li><li>找到「自定义 Provider」（自定义服务商）或「添加 Provider」按钮，点它。</li><li>按下表填写：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>填写内容</th></tr></thead><tbody><tr><td>供应商名称</td><td>填你中转站标题上的名字，方便自己认</td></tr><tr><td>官网链接</td><td>你的中转站网址</td></tr><tr><td>API 请求地址（Base URL）</td><td>中转站网址后面加上 <code>/v1</code>，或者网站上专门说明的 API 地址</td></tr><tr><td>API Key</td><td>你在控制台复制的那串 <code>sk-</code> 开头的 Key</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">💡 字段名不一样？</p><p>不同版本的 CC Switch 字段名可能略有不同。记住一个原则：<strong>只要字段要求填「官网 / 网站」，就填你的中转站网址；只要字段要求填「请求地址 / Base URL」，就填中转站网址加 <code>/v1</code>，或者网站上专门说明的 API 地址。</strong></p></div><h3 id="启用并重启-chatgpt" tabindex="-1">启用并重启 ChatGPT <a class="header-anchor" href="#启用并重启-chatgpt" aria-label="Permalink to &quot;启用并重启 ChatGPT&quot;">​</a></h3><ol><li>在 CC Switch 里把刚才添加的那一项 <strong>启用</strong>（通常是点一下开关或点「启用」按钮）。</li><li><strong>完全退出 ChatGPT，再重新打开</strong>（不是关窗口，是从 Dock / 任务栏退出后重新启动）。 <ul><li>用命令行的话：关掉终端窗口，重新开一个新的。</li></ul></li></ol><div class="warning custom-block"><p class="custom-block-title">⚠️ 这一步最容易忘</p><p>填完配置后<strong>必须重启 ChatGPT</strong>（用命令行的话就重开终端），不然它还在用旧配置。90% 的&quot;配置了没反应&quot;都是这个原因。</p></div><hr><h2 id="🎉-验证-怎么确认配置完成" tabindex="-1">🎉 验证：怎么确认配置完成 <a class="header-anchor" href="#🎉-验证-怎么确认配置完成" aria-label="Permalink to &quot;🎉 验证：怎么确认配置完成&quot;">​</a></h2><p>最后做这一步——<strong>发一条测试消息</strong>：</p><p>在 ChatGPT 的输入框里输入下面这句话，发送：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>确认一下你能正常回复，只说一句话，不要改任何文件。</span></span></code></pre></div><p><strong>看到 ChatGPT 正常回复你，恭喜，配置完成！</strong> ✅ 从这一步开始，ChatGPT 就已经连上你的中转站在工作了。</p><p><img src="'+o+`" alt="ChatGPT 首次测试对话" loading="lazy"></p><h3 id="测试前再检查一遍" tabindex="-1">测试前再检查一遍 <a class="header-anchor" href="#测试前再检查一遍" aria-label="Permalink to &quot;测试前再检查一遍&quot;">​</a></h3><p>如果 ChatGPT 没回复、报错了，按顺序检查：</p><table tabindex="0"><thead><tr><th>检查项</th><th>怎么做</th></tr></thead><tbody><tr><td>1. Provider 启用了没</td><td>打开 CC Switch，确认你刚添加的那一项是启用状态</td></tr><tr><td>2. 地址填对没</td><td>请求地址应是中转站网址 + <code>/v1</code>，或网站上专门说明的 API 地址</td></tr><tr><td>3. Key 复制完整没</td><td>回控制台重新复制一次，确认没多空格、没少字符</td></tr><tr><td>4. 重启了没</td><td>退出 ChatGPT 重新打开（命令行就重开终端）</td></tr><tr><td>5. 余额够不够</td><td>回 <a href="/guide/recharge">充值页</a> 看钱包余额</td></tr><tr><td>6. 报错代码是什么</td><td>按错误码查：<a href="/troubleshooting/network">网络与连接排查</a></td></tr></tbody></table><hr><h2 id="配置完成-接下来呢" tabindex="-1">配置完成，接下来呢？ <a class="header-anchor" href="#配置完成-接下来呢" aria-label="Permalink to &quot;配置完成，接下来呢？&quot;">​</a></h2><p>到这里，主线就全部走完了 🎉 现在你可以：</p><ul><li><strong>直接开始用</strong>：在 ChatGPT 里描述你想做的事，它会帮你写代码、改代码。</li><li><strong>进阶功能（可选）</strong>：等用顺手了，再回来看看 <a href="/guide/config-switch">CC Switch 使用教程</a>、<a href="/guide/codex-image">ChatGPT 生图教程</a>。</li><li><strong>遇到问题</strong>：去 <a href="/troubleshooting/">疑难解答总览</a> 按症状查。</li></ul><hr><details class="details custom-block"><summary>🔧 想自己研究？手动改配置文件的方式（仅技术人员）</summary><p>普通用户不需要看这一段。只有想自己研究、或者不用 CC Switch 的人才需要手动改两个文件，都在你电脑的用户目录（不是项目目录）里：</p><table tabindex="0"><thead><tr><th>系统</th><th>配置文件位置</th></tr></thead><tbody><tr><td>macOS / Linux</td><td><code>~/.codex/config.toml</code> 和 <code>~/.codex/auth.json</code></td></tr><tr><td>Windows</td><td><code>C:\\Users\\你的用户名\\.codex\\config.toml</code> 和 <code>C:\\Users\\你的用户名\\.codex\\auth.json</code></td></tr></tbody></table><p><strong>1. 改 config.toml（填请求地址）</strong>：用文本编辑器打开 <code>config.toml</code>，确认或修改成下面这样（没有这个文件就新建一个）。把 <code>mysite</code> 换成你自己好认的英文名，把 <code>https://你的中转站网址/v1</code> 换成你的实际请求地址；如果中转站上专门写了 API 地址，<code>base_url</code> 就填那个：</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model_provider = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mysite&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;gpt-5.5&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">model_providers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mysite</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;你的中转站名称&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">wire_api = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;responses&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">requires_openai_auth = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">base_url = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://你的中转站网址/v1&quot;</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">⚠️ 注意</p><p>网站没有专门说明 API 地址时，<code>base_url</code> 要带 <code>/v1</code>。只填中转站网址、不带 <code>/v1</code> 会连不上。</p></div></details><p><strong>2. 改 auth.json（填 API Key）</strong>：在同一个 <code>.codex</code> 目录里，找到或新建 <code>auth.json</code>，把 API Key 填进去：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;OPENAI_API_KEY&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;你在控制台复制的 API Key&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">安全提醒</p><p><code>auth.json</code> 里存的是你的密码（API Key），<strong>不要</strong>把它放进项目文件夹，也<strong>不要</strong>提交到 Git（代码仓库）里。</p></div><p><strong>3. 重启</strong>：保存两个文件后，关掉终端窗口，重新打开一个新的，再进入你的项目目录运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 你的项目目录</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span></span></code></pre></div><p>:::</p>`,45)])])}const u=a(d,[["render",h]]);export{k as __pageData,u as default};
